chem.bySym = {}
chem.byZ = {}
for i = 1, #chem.el do
    local e = chem.el[i]
    chem.bySym[e.sym] = e
    chem.byZ[e.z] = e
end

-- Состояние при данной температуре по справочным точкам плавления и кипения.
-- Если точка неизвестна (синтетические элементы), считаем твёрдым.
function chem.phaseAt(e, t)
    if e.boil and t >= e.boil then return "GAS" end
    if e.melt and t >= e.melt then return "LIQUID" end
    return "SOLID"
end

return chem